-- cache_generator.lua
-- Generates vim.pack cache files from parsed plugin specs

local M = {}

-- Create the output directory structure
local function ensure_cache_dir(cache_dir)
    local lua_dir = cache_dir .. "/lua"
    os.execute("mkdir -p " .. cache_dir)
    os.execute("mkdir -p " .. lua_dir)
end

-- Generate the main 00_init.lua with vim.pack.add() call
local function generate_pack_init(cache_dir, plugins)
    local output = [[
-- Generated vim.pack cache from init.md
-- DO NOT EDIT - Auto-generated by init.lua markdown parser

local lazyload = require("lazyload")
local plugins = {
]]

    local register_calls = {}

    for _, plugin in ipairs(plugins) do
        output = output .. "  {\n"
        output = output .. '    src = "' .. plugin.src .. '",\n'
        if plugin.name then
            output = output .. '    name = "' .. plugin.name .. '",\n'
        end
        if plugin.branch then
            output = output .. '    branch = "' .. plugin.branch .. '",\n'
        end
        output = output .. '    load = "' .. (plugin.load or "start") .. '",\n'

        -- Include lazy trigger fields
        if plugin.event then
            output = output .. "    event = " .. vim.inspect(plugin.event) .. ",\n"
        end
        if plugin.cmd then
            output = output .. "    cmd = " .. vim.inspect(plugin.cmd) .. ",\n"
        end
        if plugin.keys then
            output = output .. "    keys = " .. vim.inspect(plugin.keys) .. ",\n"
        end
        if plugin.ft then
            output = output .. "    ft = " .. vim.inspect(plugin.ft) .. ",\n"
        end

        output = output .. "  },\n"

        -- Collect lazy trigger registrations for after vim.pack.add
        if plugin.load == "opt" and (plugin.event or plugin.cmd or plugin.keys or plugin.ft) then
            local plugin_name = plugin.name or plugin.src:match("/([^/]-)%.?nvim?$") or plugin.src:match("/([^/]+)$")
            local triggers = {}
            if plugin.event then triggers.event = plugin.event end
            if plugin.cmd then triggers.cmd = plugin.cmd end
            if plugin.keys then triggers.keys = plugin.keys end
            if plugin.ft then triggers.ft = plugin.ft end
            table.insert(register_calls, 'lazyload.register("' .. plugin_name .. '", ' .. vim.inspect(triggers) .. ")")
        end
    end

    output = output .. "}\n\nvim.pack.add(plugins)\n\n"

    -- Add lazy trigger registrations after vim.pack.add
    for _, reg in ipairs(register_calls) do
        output = output .. reg .. "\n"
    end

    local file = assert(io.open(cache_dir .. "/00_init.lua", "w"))
    file:write(output)
    file:close()
end

-- Generate lazyload module (VimEnter queue manager)
local function generate_lazyload_module(cache_dir)
    local output = [[
-- lazyload.lua
-- Manages optional package loading through :packadd-compatible commands

local M = {}
local load_queue = {}
local loaded = {}

local function normalize_list(value)
    if value == nil then
        return {}
    end
    if type(value) == "table" then
        return value
    end
    return { value }
end

function M.load(plugin_name)
    if loaded[plugin_name] then
        return true
    end

    local ok, err = pcall(vim.cmd.packadd, plugin_name)
    if not ok then
        vim.notify(err, vim.log.levels.ERROR)
        return false
    end

    loaded[plugin_name] = true
    return true
end

function M.register(plugin_name, triggers)
    load_queue[plugin_name] = triggers or {}
end

function M.trigger_loads()
    for plugin_name, config in pairs(load_queue) do
        -- Command triggers: create user commands that load plugin then execute
        for _, cmd in ipairs(normalize_list(config.cmd)) do
            vim.api.nvim_create_user_command(cmd, function(args)
                if M.load(plugin_name) then
                    vim.cmd(cmd .. " " .. table.concat(args.fargs, " "))
                end
            end, { nargs = "*", bang = true })
        end

        -- Key triggers: create keymaps that load plugin then replay key
        for _, keymap in ipairs(normalize_list(config.keys)) do
            local lhs = type(keymap) == "table" and keymap[1] or keymap
            if lhs then
                local mode = type(keymap) == "table" and keymap.mode or "n"
                vim.keymap.set(mode or "n", lhs, function()
                    if M.load(plugin_name) then
                        vim.api.nvim_feedkeys(vim.api.nvim_replace_termcodes(lhs, true, false, true), "m", false)
                    end
                end, { desc = type(keymap) == "table" and keymap.desc or nil })
            end
        end

        -- Event triggers: autocmds that load plugin on event
        for _, evt in ipairs(normalize_list(config.event)) do
            vim.api.nvim_create_autocmd(evt, {
                callback = function()
                    M.load(plugin_name)
                end,
                once = true,
            })
        end

        -- Filetype triggers: autocmds that load plugin on filetype
        for _, filetype in ipairs(normalize_list(config.ft)) do
            vim.api.nvim_create_autocmd("FileType", {
                pattern = filetype,
                callback = function()
                    M.load(plugin_name)
                end,
                once = true,
            })
        end
    end
end

vim.api.nvim_create_autocmd("VimEnter", {
    callback = M.trigger_loads
})

return M
]]

    local file = assert(io.open(cache_dir .. "/lua/lazyload.lua", "w"))
    file:write(output)
    file:close()
end

-- Generate merge module (config registry)
local function generate_merge_module(cache_dir)
    local output = [[
-- merge.lua
-- Registry for plugin configs (opts) to be applied after plugin load

local M = {}
local config_registry = {}

function M.register(plugin_name, config)
    config_registry[plugin_name] = config
end

function M.apply_configs()
    for plugin_name, config in pairs(config_registry) do
        if config.opts and package.loaded[plugin_name] then
            local ok, plugin = pcall(require, plugin_name)
            if ok and plugin.setup then
                plugin.setup(config.opts)
            end
        end
    end
end

vim.api.nvim_create_autocmd("VimEnter", {
    callback = M.apply_configs
})

return M
]]

    local file = assert(io.open(cache_dir .. "/lua/merge.lua", "w"))
    file:write(output)
    file:close()
end

local function generate_setup_module(cache_dir, setup_blocks)
    local output = [[
-- setup.lua
-- Executes opt-in setup blocks marked as **Setup: executable** in init.md

local M = {}
local setup_blocks = {
]]

    for _, block in ipairs(setup_blocks or {}) do
        output = output .. "  " .. string.format("%q", block) .. ",\n"
    end

    output = output .. [[}
M.errors = {}

function M.run()
    M.errors = {}
    for index, block in ipairs(setup_blocks) do
        local chunk, load_err = load(block, "init.md executable setup #" .. index)
        if not chunk then
            M.errors[#M.errors + 1] = { index = index, error = tostring(load_err) }
            vim.notify(load_err, vim.log.levels.ERROR)
        else
            local ok, run_err = pcall(chunk)
            if not ok then
                M.errors[#M.errors + 1] = { index = index, error = tostring(run_err) }
                vim.notify(run_err, vim.log.levels.ERROR)
            end
        end
    end
    vim.g.init_md_setup_errors = M.errors
    return #M.errors == 0, M.errors
end

return M
]]

    local file = assert(io.open(cache_dir .. "/lua/setup.lua", "w"))
    file:write(output)
    file:close()
end

-- Generate manifest with simple hash
local function generate_manifest(cache_dir, markdown_filepath)
    local file = assert(io.open(markdown_filepath, "r"))
    local content = file:read("*a")
    file:close()

    local function simple_hash(text)
        local hash = 0
        for i = 1, #text do
            hash = (hash * 31 + string.byte(text, i)) % 0x7FFFFFFF
        end
        return string.format("%x", hash)
    end

    local hash = simple_hash(content)

    local manifest_file = assert(io.open(cache_dir .. "/manifest.txt", "w"))
    manifest_file:write(hash .. "\n")
    manifest_file:close()
end

function M.generate(cache_dir, plugins, _, markdown_filepath, setup_blocks)
    ensure_cache_dir(cache_dir)
    generate_pack_init(cache_dir, plugins)
    generate_lazyload_module(cache_dir)
    generate_merge_module(cache_dir)
    generate_setup_module(cache_dir, setup_blocks or {})
    generate_manifest(cache_dir, markdown_filepath)
end

return M
